DROP TABLE IF EXISTS `tb_attachment`;
CREATE TABLE `tb_attachment` (
  `file_id` bigint NOT NULL AUTO_INCREMENT,
  `bridge_code` varchar(30) DEFAULT NULL,
  `archive_record_id` bigint DEFAULT NULL,
  `initial_inspection_code` varchar(30) DEFAULT NULL,
