  `file_size` bigint DEFAULT NULL,
  `file_description` varchar(255) DEFAULT NULL,
  `photo_category` varchar(40) DEFAULT NULL COMMENT '桥梁照片分类',
  `upload_by` int DEFAULT NULL,
  `upload_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`file_id`),
  KEY `fk_attachment_archive` (`archive_record_id`),
  KEY `fk_attachment_initial` (`initial_inspection_code`),
  KEY `fk_attachment_ci` (`component_inspection_id`),
  KEY `fk_attachment_defect` (`defect_id`),
  KEY `fk_attachment_user` (`upload_by`),
  KEY `idx_attachment_bridge_category` (`bridge_code`,`photo_category`),
  CONSTRAINT `fk_attachment_archive` FOREIGN KEY (`archive_record_id`) REFERENCES `tb_bridge_archive_record` (`archive_record_id`),
  CONSTRAINT `fk_attachment_bridge` FOREIGN KEY (`bridge_code`) REFERENCES `tb_bridge` (`bridge_code`),
  CONSTRAINT `fk_attachment_ci` FOREIGN KEY (`component_inspection_id`) REFERENCES `tb_component_inspection` (`component_inspection_id`),
  CONSTRAINT `fk_attachment_defect` FOREIGN KEY (`defect_id`) REFERENCES `tb_defect` (`defect_id`),
  CONSTRAINT `fk_attachment_initial` FOREIGN KEY (`initial_inspection_code`) REFERENCES `tb_initial_inspection` (`initial_inspection_code`),
  CONSTRAINT `fk_attachment_user` FOREIGN KEY (`upload_by`) REFERENCES `tb_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='照片档案文件（物理表：tb_attachment）';

DROP TABLE IF EXISTS `tb_backup_record`;
CREATE TABLE `tb_backup_record` (
  `backup_id` bigint NOT NULL AUTO_INCREMENT,
  `backup_type` varchar(30) NOT NULL DEFAULT 'database' COMMENT '备份类型',
  `version_message` varchar(300) DEFAULT NULL COMMENT '版本说明',
  `file_name` varchar(255) NOT NULL,
  `file_path` varchar(500) NOT NULL,
  `file_size` bigint DEFAULT NULL,
  `sha256` varchar(64) DEFAULT NULL,
  `git_commit_hash` varchar(64) DEFAULT NULL COMMENT 'Git提交哈希',
  `git_branch` varchar(100) DEFAULT NULL COMMENT 'Git分支',
  `execute_by` int DEFAULT NULL,
  `backup_status` varchar(20) NOT NULL,
  `restore_status` varchar(20) DEFAULT NULL,
  `error_message` varchar(1000) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `restore_time` datetime DEFAULT NULL,
  PRIMARY KEY (`backup_id`),
  KEY `fk_backup_user` (`execute_by`),
  KEY `idx_backup_git_commit` (`git_commit_hash`),
  KEY `idx_backup_create_time` (`create_time`),
  CONSTRAINT `fk_backup_user` FOREIGN KEY (`execute_by`) REFERENCES `tb_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='数据库备份记录（物理表：tb_backup_record）';

