  CONSTRAINT `fk_defect_definition_part` FOREIGN KEY (`applicable_part_code`) REFERENCES `tb_part` (`part_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='初始检查和定期检查共用病害字典';

DROP TABLE IF EXISTS `tb_defect_degree`;
CREATE TABLE `tb_defect_degree` (
  `defect_degree_code` varchar(32) NOT NULL,
  `defect_degree_name` varchar(50) NOT NULL,
