  UNIQUE KEY `defect_degree_name` (`defect_degree_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='缺损程度（物理表：tb_defect_degree）';

DROP TABLE IF EXISTS `tb_evaluation_history`;
CREATE TABLE `tb_evaluation_history` (
