  CONSTRAINT `fk_eval_bridge` FOREIGN KEY (`bridge_code`) REFERENCES `tb_bridge` (`bridge_code`),
  CONSTRAINT `fk_eval_category` FOREIGN KEY (`check_category_code`) REFERENCES `tb_check_category` (`check_category_code`)
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='检测评定历史（物理表：tb_evaluation_history）';

DROP TABLE IF EXISTS `tb_initial_component_inspection`;
CREATE TABLE `tb_initial_component_inspection` (
  `initial_component_inspection_id` bigint NOT NULL AUTO_INCREMENT,
  `initial_inspection_code` varchar(30) NOT NULL,
  `bridge_component_id` bigint NOT NULL,
  `item_code` varchar(20) NOT NULL,
  `measured_value` text,
  `inspection_description` text,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
