  KEY `fk_ici_bridge_component` (`bridge_component_id`),
  KEY `fk_ici_item` (`item_code`),
  CONSTRAINT `fk_ici_bridge_component` FOREIGN KEY (`bridge_component_id`) REFERENCES `tb_bridge_specific_component` (`bridge_component_id`),
  CONSTRAINT `fk_ici_initial` FOREIGN KEY (`initial_inspection_code`) REFERENCES `tb_initial_inspection` (`initial_inspection_code`),
  CONSTRAINT `fk_ici_item` FOREIGN KEY (`item_code`) REFERENCES `tb_initial_inspection_item_definition` (`item_code`)
) ENGINE=InnoDB AUTO_INCREMENT=421 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='初始检查桥墩及具体部件检测记录';

DROP TABLE IF EXISTS `tb_initial_inspection`;
CREATE TABLE `tb_initial_inspection` (
  `initial_inspection_code` varchar(30) NOT NULL,
  `task_id` varchar(30) DEFAULT NULL,
  `version_no` int NOT NULL DEFAULT '1',
  `effective_flag` tinyint NOT NULL DEFAULT '1',
  `record_form_no` varchar(60) DEFAULT NULL COMMENT '初始检查表专属编号',
  `bridge_code` varchar(30) NOT NULL,
  `inspection_date` date NOT NULL,
  `inspection_org` varchar(100) DEFAULT NULL,
  `inspectors` varchar(100) DEFAULT NULL,
  `bridge_engineer` varchar(50) DEFAULT NULL,
  `weather_temperature` varchar(100) DEFAULT NULL,
  `main_span_structure` varchar(100) DEFAULT NULL,
  `maximum_span` decimal(10,2) DEFAULT NULL,
  `span_combination` varchar(200) DEFAULT NULL,
  `structure_form` varchar(200) DEFAULT NULL,
  `construction_method` varchar(200) DEFAULT NULL,
  `construction_rework` text,
  `reinforcement_info` text,
  `missing_archive_drawings` text,
  `defect_advice` text,
  `status` varchar(20) NOT NULL DEFAULT 'draft',
  `reviewer_id` int DEFAULT NULL COMMENT '审核人员编号',
  `review_opinion` varchar(500) DEFAULT NULL COMMENT '审核意见',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `archive_time` datetime DEFAULT NULL COMMENT '归档时间',
  `create_by` int DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`initial_inspection_code`),
  UNIQUE KEY `uk_initial_record_form_no` (`record_form_no`),
  UNIQUE KEY `uk_initial_task_id` (`task_id`),
  KEY `fk_initial_creator` (`create_by`),
  KEY `idx_initial_bridge_effective` (`bridge_code`,`effective_flag`,`inspection_date`),
  KEY `idx_initial_task_id` (`task_id`),
  KEY `idx_initial_review_status` (`status`,`review_time`),
  KEY `fk_initial_reviewer` (`reviewer_id`),
  CONSTRAINT `fk_initial_bridge` FOREIGN KEY (`bridge_code`) REFERENCES `tb_bridge` (`bridge_code`),
  CONSTRAINT `fk_initial_creator` FOREIGN KEY (`create_by`) REFERENCES `tb_user` (`user_id`),
  CONSTRAINT `fk_initial_reviewer` FOREIGN KEY (`reviewer_id`) REFERENCES `tb_user` (`user_id`),
  CONSTRAINT `fk_initial_task` FOREIGN KEY (`task_id`) REFERENCES `tb_inspection_task` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='初始检查记录（物理表：tb_initial_inspection）';

DROP TABLE IF EXISTS `tb_initial_inspection_item`;
CREATE TABLE `tb_initial_inspection_item` (
  `item_record_id` bigint NOT NULL AUTO_INCREMENT,
  `initial_inspection_code` varchar(30) NOT NULL,
  `item_code` varchar(20) NOT NULL,
  `applicable_flag` tinyint NOT NULL DEFAULT '1',
  `trigger_result` varchar(200) DEFAULT NULL,
  `measured_value` text,
  `inspection_description` text,
  `defect_definition_code` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`item_record_id`),
  UNIQUE KEY `uk_initial_item` (`initial_inspection_code`,`item_code`),
  KEY `fk_initial_item_definition` (`item_code`),
  KEY `fk_initial_item_defect_definition` (`defect_definition_code`),
  CONSTRAINT `fk_initial_item_defect_definition` FOREIGN KEY (`defect_definition_code`) REFERENCES `tb_defect_definition` (`defect_definition_code`),
  CONSTRAINT `fk_initial_item_definition` FOREIGN KEY (`item_code`) REFERENCES `tb_initial_inspection_item_definition` (`item_code`),
  CONSTRAINT `fk_initial_item_record` FOREIGN KEY (`initial_inspection_code`) REFERENCES `tb_initial_inspection` (`initial_inspection_code`)
) ENGINE=InnoDB AUTO_INCREMENT=2092 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='初始检查检测项目（物理表：tb_initial_inspection_item）';

DROP TABLE IF EXISTS `tb_initial_inspection_item_definition`;
CREATE TABLE `tb_initial_inspection_item_definition` (
  `item_code` varchar(20) NOT NULL,
  `item_name` varchar(100) NOT NULL,
  `unit` varchar(30) DEFAULT NULL,
  `item_category` varchar(50) DEFAULT NULL,
  `description` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`item_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='初始检查项目定义（物理表：tb_initial_inspection_item_definition）';

DROP TABLE IF EXISTS `tb_inspection_archive`;
CREATE TABLE `tb_inspection_archive` (
  `archive_id` bigint NOT NULL AUTO_INCREMENT,
  `inspection_type` varchar(20) NOT NULL COMMENT 'initial 或 periodic',
  `record_code` varchar(30) NOT NULL COMMENT '检查记录编号',
  `bridge_code` varchar(30) NOT NULL,
  `task_id` varchar(30) DEFAULT NULL,
