  KEY `fk_inspection_archive_user` (`archived_by`),
  KEY `idx_inspection_archive_bridge` (`bridge_code`,`archived_time`),
  KEY `idx_inspection_archive_task` (`task_id`),
  CONSTRAINT `fk_inspection_archive_bridge` FOREIGN KEY (`bridge_code`) REFERENCES `tb_bridge` (`bridge_code`),
  CONSTRAINT `fk_inspection_archive_task` FOREIGN KEY (`task_id`) REFERENCES `tb_inspection_task` (`task_id`),
  CONSTRAINT `fk_inspection_archive_user` FOREIGN KEY (`archived_by`) REFERENCES `tb_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='审核通过的初始检查和定期检查档案';

DROP TABLE IF EXISTS `tb_inspection_task`;
CREATE TABLE `tb_inspection_task` (
  `task_id` varchar(30) NOT NULL,
  `bridge_code` varchar(30) NOT NULL,
  `inspection_type` varchar(20) NOT NULL,
  `inspection_level` varchar(10) DEFAULT NULL,
