  UNIQUE KEY `part_name` (`part_name`),
  UNIQUE KEY `uk_part_sort_order` (`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='部位（物理表：tb_part）';

