  KEY `fk_periodic_creator` (`create_by`),
  KEY `idx_periodic_task_id` (`task_id`),
  KEY `idx_periodic_review_status` (`status`,`review_time`),
  KEY `fk_periodic_reviewer` (`reviewer_id`),
  CONSTRAINT `fk_periodic_bridge` FOREIGN KEY (`bridge_code`) REFERENCES `tb_bridge` (`bridge_code`),
  CONSTRAINT `fk_periodic_creator` FOREIGN KEY (`create_by`) REFERENCES `tb_user` (`user_id`),
  CONSTRAINT `fk_periodic_rating` FOREIGN KEY (`rating_level_code`) REFERENCES `tb_rating_level` (`rating_level_code`),
  CONSTRAINT `fk_periodic_reviewer` FOREIGN KEY (`reviewer_id`) REFERENCES `tb_user` (`user_id`),
  CONSTRAINT `fk_periodic_task` FOREIGN KEY (`task_id`) REFERENCES `tb_inspection_task` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='定期检查记录（物理表：tb_periodic_inspection）';

DROP TABLE IF EXISTS `tb_rating_level`;
