  `rating_level_code` varchar(32) NOT NULL,
  `rating_level_name` varchar(50) NOT NULL,
  PRIMARY KEY (`rating_level_code`),
  UNIQUE KEY `rating_level_name` (`rating_level_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='技术状况等级（物理表：tb_rating_level）';

DROP TABLE IF EXISTS `tb_report`;
CREATE TABLE `tb_report` (
  `report_id` varchar(40) NOT NULL,
  `task_id` varchar(30) DEFAULT NULL,
  `initial_inspection_code` varchar(30) DEFAULT NULL,
  `periodic_inspection_code` varchar(30) DEFAULT NULL,
  `report_type` varchar(30) NOT NULL,
  `version_no` varchar(20) NOT NULL,
  `file_format` varchar(20) DEFAULT NULL,
  `file_path` varchar(500) DEFAULT NULL,
  `report_status` varchar(20) NOT NULL DEFAULT '草稿',
  `generation_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
