  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`role_id`),
  UNIQUE KEY `role_code` (`role_code`),
  UNIQUE KEY `role_name` (`role_name`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='角色（物理表：tb_role）';

DROP TABLE IF EXISTS `tb_route`;
CREATE TABLE `tb_route` (
  `route_code` varchar(20) NOT NULL,
  `route_name` varchar(100) NOT NULL,
  `route_grade` varchar(20) DEFAULT NULL,
  `route_geometry` longtext COMMENT '高德 GCJ-02 路线坐标串',
  `route_distance` decimal(12,2) DEFAULT NULL COMMENT '规划路线长度（米）',
  `origin_longitude` decimal(10,6) DEFAULT NULL,
  `origin_latitude` decimal(10,6) DEFAULT NULL,
  `destination_longitude` decimal(10,6) DEFAULT NULL,
  `destination_latitude` decimal(10,6) DEFAULT NULL,
