  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`route_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='路线（物理表：tb_route）';

DROP TABLE IF EXISTS `tb_task_assignment`;
CREATE TABLE `tb_task_assignment` (
  `assignment_id` varchar(40) NOT NULL,
  `task_id` varchar(30) NOT NULL,
  `user_id` int NOT NULL,
  `assignment_status` varchar(20) NOT NULL DEFAULT '待分配',
  `assign_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `accept_time` datetime DEFAULT NULL,
  `complete_time` datetime DEFAULT NULL,
  PRIMARY KEY (`assignment_id`),
  UNIQUE KEY `uk_task_user` (`task_id`,`user_id`),
  KEY `fk_assignment_user` (`user_id`),
