  CONSTRAINT `fk_assignment_user` FOREIGN KEY (`user_id`) REFERENCES `tb_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='任务分配（物理表：tb_task_assignment）';

DROP TABLE IF EXISTS `tb_task_status_history`;
CREATE TABLE `tb_task_status_history` (
  `history_id` varchar(40) NOT NULL,
  `task_id` varchar(30) NOT NULL,
  `from_status` varchar(20) DEFAULT NULL,
  `to_status` varchar(20) NOT NULL,
