  `operation_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `opinion` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`history_id`),
  KEY `fk_history_task` (`task_id`),
  KEY `fk_history_operator` (`operator_id`),
  CONSTRAINT `fk_history_operator` FOREIGN KEY (`operator_id`) REFERENCES `tb_user` (`user_id`),
  CONSTRAINT `fk_history_task` FOREIGN KEY (`task_id`) REFERENCES `tb_inspection_task` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='任务状态历史（物理表：tb_task_status_history）';

DROP TABLE IF EXISTS `tb_user`;
CREATE TABLE `tb_user` (
  `user_id` int NOT NULL AUTO_INCREMENT,
  `user_name` varchar(50) NOT NULL,
  `login_account` varchar(50) NOT NULL,
